def find_exact_venmo_email(first_name):
    venmo_results = []
    page_index = 0
    while True:
        page = apis.venmo.search_users(access_token=venmo_token, query=first_name, page_index=page_index, page_limit=20)
        if not page:
            break
        venmo_results.extend(page)
        page_index += 1
    return next(item['email'] for item in venmo_results if item['first_name'] == first_name and '@example.com' not in item['email'])
exact_venmo_emails = {
    name: find_exact_venmo_email(first_name)
    for name, first_name in [
        ('Stephen', 'Stephen'),
        ('Sabrina', 'Sabrina'),
        ('Jamie', 'Jamie'),
        ('Anita', 'Anita')
    ]
}
